type Money struct {
    cents    int64
    currency string
}

func NewMoney(cents int64, currency string) (Money, error) {
    if len(currency) != 3 { return Money{}, fmt.Errorf("bad currency %q", currency) }
    return Money{cents, currency}, nil
}

func (m Money) Equal(o Money) bool { return m.cents == o.cents && m.currency == o.currency }
